    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">xÔy</span> و <span dir=\"ltr\" class=\"expr pt\">yÔz</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">xÔy = 108°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[Ou)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">xÔy</span>  و  <span dir=\"ltr\" class=\"expr pt\">[Ot)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">yÔz</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">tÔu.</span> نختار المنصّف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: [Ou)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">xÔy</span>  و  <span dir=\"ltr\" class=\"expr pt\">xÔy = 108°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[Ou)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">xÔy</span>  و  <span dir=\"ltr\" class=\"expr pt\">xÔy = 108°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">uÔy = 108° : 2 = 54°</span>"},{"quoi":"القاعدة","math":"زاويتان متكاملتان مجموع قيسيهما <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">xÔy</span> و <span dir=\"ltr\" class=\"expr pt\">yÔz</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">xÔy = 108°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">yÔz = 180° - 108° = 72°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[Ot)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">yÔz</span>  و  <span dir=\"ltr\" class=\"expr pt\">yÔz = 72°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">tÔy = 72° : 2 = 36°</span>"},{"quoi":"القاعدة","math":"إذا كانت زاويتان متجاورتين فإنّ قيس الزاوية الكبرى يساوي مجموع قيسيهما"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">uÔy</span> و <span dir=\"ltr\" class=\"expr pt\">tÔy</span> متجاورتان  و  <span dir=\"ltr\" class=\"expr pt\">uÔy = 54°</span>  و  <span dir=\"ltr\" class=\"expr pt\">tÔy = 36°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">tÔu = 54° + 36° = 90°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">tÔu = 90°</span>"}],
