    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">xÔy = 45°</span>  و  <span dir=\"ltr\" class=\"expr pt\">tÔz = 99°</span>  و  <span dir=\"ltr\" class=\"expr pt\">xÔz = 180°</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">tÔy.</span> نختار علاقة شال للزوايا لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: tÔx</span> و <span dir=\"ltr\" class=\"expr pt\">tÔz</span> متجاورتان  و  <span dir=\"ltr\" class=\"expr pt\">xÔz = 180°</span>  و  <span dir=\"ltr\" class=\"expr pt\">tÔz = 99°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"إذا كانت زاويتان متجاورتين فإنّ قيس الزاوية الكبرى يساوي مجموع قيسيهما"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">tÔx</span> و <span dir=\"ltr\" class=\"expr pt\">tÔz</span> متجاورتان  و  <span dir=\"ltr\" class=\"expr pt\">xÔz = 180°</span>  و  <span dir=\"ltr\" class=\"expr pt\">tÔz = 99°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">tÔx = 180° - 99° = 81°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">xÔy</span> و <span dir=\"ltr\" class=\"expr pt\">tÔy</span> متجاورتان  و  <span dir=\"ltr\" class=\"expr pt\">tÔx = 81°</span>  و  <span dir=\"ltr\" class=\"expr pt\">xÔy = 45°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">tÔy = 81° - 45° = 36°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">tÔy = 36°</span>"}],
